    function assetPath(path) {
      const clean = String(path || "").replace(/^\.\//, "").replace(/^\/+/, "");
      return clean ? pageRootPrefix() + clean : "";
    }

    function srcOf(src) {
      const key = String(src || "").replace(location.origin, "");
      const mapped = embeddedAssets[src] || embeddedAssets[key] || "";
      return mapped ? assetPath(mapped) : window.fallbackImage || assetPath("./assets/images/products_shaker.png");
    }

    function setAssetImages() {
      document.querySelectorAll("[data-asset]").forEach(img => {
        img.src = srcOf(img.dataset.asset);
      });
    }

    function syncStaticLinks() {
      document.querySelectorAll("a[data-category]").forEach(link => {
        link.setAttribute("href", categoryHref(link.dataset.category));
      });
      document.querySelectorAll("a[data-product]").forEach(link => {
        const product = productBySlugOrId(link.dataset.product);
        if (product) link.setAttribute("href", productPath(product));
        link.removeAttribute("target");
        link.removeAttribute("rel");
      });
      document.querySelectorAll("a[data-brand-filter]").forEach(link => {
        link.setAttribute("href", brandPath(link.dataset.brandFilter));
      });
      document.querySelectorAll("a[data-home-link]").forEach(link => {
        link.setAttribute("href", homePath());
      });
    }

    function escapeHtml(value) {
      return String(value || "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[char]));
    }

    function normalize(value) {
      return String(value || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ł/g, "l").replace(/[^a-z0-9]+/g, " ").trim();
    }

    function productScore(product) {
      return Number(product.rating || 0) * 100 + Number(product.reviewsCount || 0) + (product.status?.bestseller ? 70 : 0) + (product.status?.recommended ? 30 : 0);
    }

    function productImage(product) {
      return srcOf(product.image || product.gallery?.[0] || "/products/shaker.png");
    }

    function discountPercent(product) {
      if (!product.oldPrice || product.oldPrice <= product.price) return 0;
      return Math.max(5, Math.round(((product.oldPrice - product.price) / product.oldPrice) * 100));
    }

    function categoryRouteSlug(slug) {
      if (!slug || slug === "all") return "sklep";
      const direct = routeAliases[slug];
      if (direct) return direct;
      const parts = String(slug).split(":");
      if (parts.length > 1) {
        const [categorySlug, subcategorySlug] = parts;
        const duplicateSubcategory = categories.filter(category => (category.subcategories || []).some(item => item.slug === subcategorySlug)).length > 1;
        if (duplicateSubcategory) return categorySlug + "-" + subcategorySlug;
      }
      const last = parts.pop();
      return routeAliases[last] || last;
    }

    function categoryHref(slug) {
      return categoryPath(slug);
    }

    function staticPagePath(folder, slug) {
      return pageRootPrefix() + folder + "/" + slug + ".html";
    }

    function currentBasePath() {
      const path = location.pathname;
      if (path.includes("/kategoria/")) return path.split("/kategoria/")[0] || "/";
      if (path.includes("/produkt/")) return path.split("/produkt/")[0] || "/";
      if (path.includes("/producent/")) return path.split("/producent/")[0] || "/";
      if (path.includes("/szukaj/")) return path.split("/szukaj/")[0] || "/";
      if (path.includes("/sklep/")) return path.split("/sklep/")[0] || "/";
      if (path.includes("/koszyk/")) return path.split("/koszyk/")[0] || "/";
      if (path.includes("/moje-konto/")) return path.split("/moje-konto/")[0] || "/";
      return path.replace(/\/(?:index\.html|404\.html)?$/, "") || "/";
    }

    function shopPath() {
      return pageRootPrefix() + "shop.html";
    }

    function categoryPath(slug) {
      if (!slug || slug === "all") return shopPath();
      return staticPagePath("categories", categoryRouteSlug(slug));
    }

    function homePath() {
      return pageRootPrefix() + "index.html";
    }

    function safePush(state, path) {
      try {
        history.pushState(state, "", path);
      } catch {}
    }

    function slugify(value) {
      return normalize(value).replace(/\s+/g, "-");
    }

    function productSlug(product) {
      return product.slug || slugify(product.name);
    }

    function productHref(product) {
      return productPath(product);
    }

    function productPath(product) {
      return staticPagePath("products", productSlug(product));
    }

    function brandSlug(value) {
      return slugify(value);
    }

    function brandHref(brand) {
      return brandPath(brand);
    }

    function brandPath(brand) {
      return staticPagePath("producers", brandSlug(brand));
    }

    function searchPath(query) {
      return pageRootPrefix() + "search.html?q=" + encodeURIComponent(query || "");
    }

    function categorySlugFromRoute(route) {
      if (!route || route === "sklep" || route === "wszystkie-produkty") return "all";
      if (routeCategoryMap[route]) return routeCategoryMap[route];
      const root = categories.find(category => category.slug === route);
      if (root) return root.slug;
      for (const category of categories) {
        const sub = category.subcategories?.find(item => category.slug + "-" + item.slug === route);
        if (sub) return category.slug + ":" + sub.slug;
      }
      for (const category of categories) {
        const sub = category.subcategories?.find(item => item.slug === route);
        if (sub) return category.slug + ":" + sub.slug;
      }
      return route;
    }

    function categoryFromLocation() {
      if (location.pathname.match(/\/(?:sklep\/?|shop\.html)$/)) return "all";
      const fileMatch = location.pathname.match(/\/categories\/([^/]+)\.html$/);
      if (fileMatch) return categorySlugFromRoute(decodeURIComponent(fileMatch[1]));
      const match = location.pathname.match(/\/kategoria\/([^/]+)/);
      if (match) return categorySlugFromRoute(decodeURIComponent(match[1]));
      const queryCategory = new URLSearchParams(location.search).get("category");
      return queryCategory ? categorySlugFromRoute(queryCategory) : "";
    }

    function productFromLocation() {
      const fileMatch = location.pathname.match(/\/products\/([^/]+)\.html$/);
      if (fileMatch) return decodeURIComponent(fileMatch[1]);
      const match = location.pathname.match(/\/produkt\/([^/]+)/);
      return match ? decodeURIComponent(match[1]) : "";
    }

    function brandFromLocation() {
      const fileMatch = location.pathname.match(/\/producers\/([^/]+)\.html$/);
      if (fileMatch) return brandNameFromRoute(decodeURIComponent(fileMatch[1]));
      const match = location.pathname.match(/\/producent\/([^/]+)/);
      if (!match) return "";
      return brandNameFromRoute(decodeURIComponent(match[1]));
    }

    function brandNameFromRoute(route) {
      return [...new Set(products.map(product => product.brand).filter(Boolean))]
        .find(brand => brandSlug(brand) === route) || route.replace(/-/g, " ");
    }

    function searchFromLocation() {
      if (!location.pathname.match(/\/(?:szukaj\/?|search\.html)$/)) return "";
      return new URLSearchParams(location.search).get("q") || "";
    }

    function matchesCategorySlug(product, slug) {
      if (!slug || slug === "all") return true;
      if (slug === "rekawice") return product.categorySlug === "sporty-walki" && String(product.subcategorySlug || "").includes("rekawice");
      if (slug === "ochraniacze") return product.categorySlug === "sporty-walki" && /ochraniacze|kaski/.test(String(product.subcategorySlug || ""));
      if (slug === "odziez") return String(product.categorySlug || "").startsWith("odziez");
      if (slug.includes(":")) {
        const [cat, sub] = slug.split(":");
        return product.categorySlug === cat && product.subcategorySlug === sub;
      }
      if (slug === "bestsellery") return product.status?.bestseller;
      if (slug === "nowosci") return product.status?.new;
      if (slug === "wyprzedaz") return product.oldPrice || product.status?.sale || product.categorySlug === "wyprzedaz";
      return product.categorySlug === slug;
    }

    function categoryFallbackSlug(slug) {
      return "";
    }

    function categoryProductsForSlug(slug) {
      return products.filter(product => matchesCategorySlug(product, slug));
    }

    function categoryInfo(slug) {
      if (slug === "all") {
        return { name: "Wszystkie produkty", description: categoryDescriptions.all, breadcrumbs: ["Wszystkie produkty"] };
      }
      if (slug === "nowosci") {
        return { name: "Nowości", description: "Nowe produkty w sklepie FIGHTSPORTS.", breadcrumbs: ["Nowości"] };
      }
      if (slug === "bestsellery") {
        return { name: "Bestsellery", description: "Najczęściej wybierane produkty FIGHTSPORTS.", breadcrumbs: ["Bestsellery"] };
      }
      if (specialCategoryInfo[slug]) return specialCategoryInfo[slug];
      const [catSlug, subSlug] = String(slug).split(":");
      const category = categories.find(item => item.slug === catSlug);
      const subcategory = category?.subcategories?.find(item => item.slug === subSlug);
      const name = categoryNameOverrides[slug] || subcategory?.name || category?.name || slug.replace(/-/g, " ");
      const description = categoryDescriptions[slug] || subcategory?.description || category?.description || "Produkty z wybranej kategorii FIGHTSPORTS.";
      const breadcrumbs = [];
      if (category?.name && subSlug) breadcrumbs.push(category.name);
      const group = categoryTrailGroups[subSlug];
      if (group) breadcrumbs.push(group);
      breadcrumbs.push(name);
      return { name, description, breadcrumbs };
    }

    function renderBreadcrumbs(info, slug) {
      const [catSlug, subSlug] = String(slug).split(":");
      const category = categories.find(item => item.slug === catSlug);
      const parts = ['<button type="button" data-home-link>Strona główna</button>'];
      if (specialCategoryInfo[slug]) {
        info.breadcrumbs.forEach(part => parts.push('<span>/</span><span>' + escapeHtml(part) + '</span>'));
        return parts.join("");
      }
      if (category?.name && subSlug) {
        parts.push('<span>/</span><a href="' + categoryHref(category.slug) + '" data-category="' + category.slug + '">' + escapeHtml(category.name) + '</a>');
      }
      const group = subSlug ? categoryTrailGroups[subSlug] : "";
      if (group) parts.push('<span>/</span><span>' + escapeHtml(group) + '</span>');
      parts.push('<span>/</span><span>' + escapeHtml(info.name) + '</span>');
      return parts.join("");
    }

    function renderHeaderNav() {
      // v29: desktop ma dokładnie tę samą kolejność głównych kategorii co menu mobilne.
      const preferred = [
        ["odzywki-i-suplementy", "Suplementy i odżywki"],
        ["sporty-walki", "Sporty walki"],
        ["odziez-meska", "Odzież męska"],
        ["odziez-damska", "Odzież damska"],
        ["odziez-dziecieca", "Odzież dziecięca"],
        ["obuwie-sportowe", "Obuwie sportowe"],
        ["akcesoria", "Akcesoria"],
        ["sprzet-sportowy", "Sprzęt sportowy"],
        ["nowosci", "Nowości"],
        ["wyprzedaz", "Wyprzedaż"]
      ];
      byId("categoryNav").innerHTML = preferred.map(([slug, label]) => {
        const active = slug === activeCategory || activeCategory.startsWith(slug + ":");
        return '<a class="category-pill ' + (active ? "active" : "") + '" href="' + categoryHref(slug) + '" data-category="' + slug + '">' + escapeHtml(label) + "</a>";
      }).join("");

      // Desktopowe menu „Kategorie” korzysta z tej samej struktury co mobile:
      // Suplementy → Sporty walki → odzież → obuwie → akcesoria → sprzęt → nowości → wyprzedaż.
      const desktopCategoryPanel = document.querySelector('[data-mega-panel="categories"]');
      if (desktopCategoryPanel) {
        const desktopCategories = categories.filter(category => preferred.some(([slug]) => slug === category.slug));
        desktopCategoryPanel.innerHTML = `
          <div class="mega-tabs fs-desktop-category-tabs" role="tablist" aria-label="Kategorie sklepu">
            ${desktopCategories.map((category, index) => `
              <button class="${index === 0 ? "active" : ""}" type="button" role="tab" aria-selected="${index === 0 ? "true" : "false"}" data-mega-tab="${escapeHtml(category.slug)}">${escapeHtml(category.name)}</button>
            `).join("")}
          </div>
          <div class="mega-content fs-desktop-category-content">
            ${desktopCategories.map((category, index) => `
              <div class="mega-tab-panel fs-desktop-category-panel ${index === 0 ? "active" : ""}" data-mega-content="${escapeHtml(category.slug)}">
                <div class="fs-desktop-category-heading">
                  <a href="${categoryHref(category.slug)}" data-category="${escapeHtml(category.slug)}">${escapeHtml(category.name)}</a>
                  <span>${escapeHtml(category.description || "Zobacz produkty z tej kategorii.")}</span>
                </div>
                <div class="fs-desktop-subcategory-grid">
                  ${(category.subcategories || []).length
                    ? category.subcategories.map(subcategory => `
                        <a href="${categoryHref(category.slug + ":" + subcategory.slug)}" data-category="${escapeHtml(category.slug + ":" + subcategory.slug)}">${escapeHtml(subcategory.name)}</a>
                      `).join("")
                    : `<a class="fs-desktop-category-all" href="${categoryHref(category.slug)}" data-category="${escapeHtml(category.slug)}">Zobacz wszystkie produkty</a>`}
                </div>
              </div>
            `).join("")}
          </div>
        `;
      }

      // Mobile navigation is rendered in HTML and managed by fs-mobile-nav.js.
      const brandBox = byId("megaBrandsList");
      if (brandBox) {
        const brands = [...new Set(products.map(product => product.brand).filter(Boolean))]
          .sort((a, b) => a.localeCompare(b, "pl"))
          .slice(0, 32);
        brandBox.innerHTML = brands.map(brand => '<a href="' + brandHref(brand) + '" data-brand-filter="' + escapeHtml(brand) + '">' + escapeHtml(brand) + '</a>').join("");
      }
    }

    function renderHero() {
      byId("heroSlides").innerHTML = heroSlides.map((slide, index) => `
        <article class="hero-slide ${index === activeSlide ? "active" : ""}" data-slide="${index}">
          <div class="hero-copy">
            <span class="eyebrow">${escapeHtml(slide.label)}</span>
            <h1>${escapeHtml(slide.title)}</h1>
            <p>${escapeHtml(slide.copy)}</p>
            <div class="hero-actions">
              <a class="primary-button" href="${categoryHref(slide.category)}" data-category="${slide.category}">${escapeHtml(slide.action)}</a>
            </div>
          </div>
          <a class="hero-art" href="${categoryHref(slide.category)}" data-category="${slide.category}" aria-label="${escapeHtml(slide.action)}">
            <img src="${srcOf(slide.image)}" alt="${escapeHtml(slide.title)}" onerror="this.src=fallbackImage" />
          </a>
        </article>
      `).join("");
      updateHeroDots();
    }

    function updateHeroDots() {
      const dots = byId("heroDots");
      if (!dots) return;
      dots.innerHTML = heroSlides.map((_, index) =>
        '<button class="hero-dot ' + (index === activeSlide ? "active" : "") + '" type="button" data-hero-dot="' + index + '" aria-label="Slajd ' + (index + 1) + '"></button>'
      ).join("");
    }

    function animateHeroTo(nextIndex, direction, fromDrag = null) {
      if (heroAnimating || nextIndex === activeSlide) return;
      const slides = Array.from(document.querySelectorAll("#heroSlides .hero-slide"));
      const current = slides[activeSlide];
      const next = slides[nextIndex];
      const carousel = byId("heroCarousel");
      if (!current || !next || !carousel) {
        activeSlide = nextIndex;
        renderHero();
        return;
      }

      heroAnimating = true;
      const width = Math.max(1, carousel.getBoundingClientRect().width);
      const dir = direction >= 0 ? 1 : -1;
      const startCurrent = fromDrag == null ? 0 : fromDrag;
      const startNext = fromDrag == null ? dir * width : dir * width + fromDrag;

      current.classList.add("hero-swiping");
      next.classList.add("hero-swiping");
      next.style.pointerEvents = "none";
      current.style.transform = `translateX(${startCurrent}px)`;
      next.style.transform = `translateX(${startNext}px)`;

      requestAnimationFrame(() => requestAnimationFrame(() => {
        current.style.transform = `translateX(${-dir * width}px)`;
        next.style.transform = "translateX(0px)";
      }));

      window.setTimeout(() => {
        current.classList.remove("active", "hero-swiping", "hero-dragging");
        next.classList.remove("hero-swiping", "hero-dragging");
        next.classList.add("active");
        current.removeAttribute("style");
        next.removeAttribute("style");
        activeSlide = nextIndex;
        heroAnimating = false;
        updateHeroDots();
      }, 380);
    }

    function moveHero(direction) {
      if (heroAnimating) return;
      const nextIndex = (activeSlide + direction + heroSlides.length) % heroSlides.length;
      animateHeroTo(nextIndex, direction);
      restartHeroTimer();
    }

    function bindHeroSwipe() {
      const carousel = byId("heroCarousel");
      if (!carousel || heroSwipeBound) return;
      heroSwipeBound = true;
      let startX = 0;
      let startY = 0;
      let dx = 0;
      let dragging = false;
      let horizontal = false;
      let pointerId = null;
      let suppressClickUntil = 0;

      function resetDrag(animateBack = true) {
        const slides = Array.from(document.querySelectorAll("#heroSlides .hero-slide"));
        const current = slides[activeSlide];
        if (!current) return;
        const direction = dx < 0 ? 1 : -1;
        const nextIndex = (activeSlide + direction + heroSlides.length) % heroSlides.length;
        const next = slides[nextIndex];
        if (animateBack) {
          current.classList.add("hero-swiping");
          current.classList.remove("hero-dragging");
          current.style.transform = "translateX(0px)";
          if (next) {
            const width = Math.max(1, carousel.getBoundingClientRect().width);
            next.classList.add("hero-swiping");
            next.classList.remove("hero-dragging");
            next.style.transform = `translateX(${direction * width}px)`;
          }
          window.setTimeout(() => {
            current.classList.remove("hero-swiping");
            current.removeAttribute("style");
            if (next) {
              next.classList.remove("hero-swiping");
              next.removeAttribute("style");
            }
          }, 380);
        } else {
          current.classList.remove("hero-dragging");
          current.removeAttribute("style");
          if (next) {
            next.classList.remove("hero-dragging");
            next.removeAttribute("style");
          }
        }
      }

      carousel.addEventListener("pointerdown", event => {
        if (heroAnimating || event.pointerType === "mouse") return;
        pointerId = event.pointerId;
        startX = event.clientX;
        startY = event.clientY;
        dx = 0;
        dragging = true;
        horizontal = false;
        clearInterval(slideTimer);
      });

      carousel.addEventListener("pointermove", event => {
        if (!dragging || event.pointerId !== pointerId || heroAnimating) return;
        dx = event.clientX - startX;
        const dy = event.clientY - startY;
        if (!horizontal) {
          if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
          if (Math.abs(dy) > Math.abs(dx)) {
            dragging = false;
            restartHeroTimer();
            return;
          }
          horizontal = true;
          try { carousel.setPointerCapture(pointerId); } catch (_) {}
        }
        event.preventDefault();
        const width = Math.max(1, carousel.getBoundingClientRect().width);
        const direction = dx < 0 ? 1 : -1;
        const nextIndex = (activeSlide + direction + heroSlides.length) % heroSlides.length;
        const slides = Array.from(document.querySelectorAll("#heroSlides .hero-slide"));
        const current = slides[activeSlide];
        const next = slides[nextIndex];
        if (!current || !next) return;
        current.classList.add("hero-dragging");
        next.classList.add("hero-dragging");
        next.style.pointerEvents = "none";
        current.style.transform = `translateX(${dx}px)`;
        next.style.transform = `translateX(${direction * width + dx}px)`;
      }, { passive: false });

      function endSwipe(event) {
        if (!dragging || (pointerId !== null && event.pointerId !== pointerId)) return;
        dragging = false;
        if (!horizontal) {
          restartHeroTimer();
          return;
        }
        const width = Math.max(1, carousel.getBoundingClientRect().width);
        const threshold = Math.min(90, width * 0.18);
        if (Math.abs(dx) >= threshold) {
          suppressClickUntil = Date.now() + 450;
          const direction = dx < 0 ? 1 : -1;
          const nextIndex = (activeSlide + direction + heroSlides.length) % heroSlides.length;
          const slides = Array.from(document.querySelectorAll("#heroSlides .hero-slide"));
          slides.forEach(slide => slide.classList.remove("hero-dragging"));
          animateHeroTo(nextIndex, direction, dx);
          restartHeroTimer();
        } else {
          resetDrag(true);
          restartHeroTimer();
        }
        dx = 0;
        horizontal = false;
        pointerId = null;
      }

      carousel.addEventListener("pointerup", endSwipe);
      carousel.addEventListener("pointercancel", endSwipe);
      carousel.addEventListener("click", event => {
        if (Date.now() < suppressClickUntil) {
          event.preventDefault();
          event.stopPropagation();
        }
      }, true);
    }

    function restartHeroTimer() {
      clearInterval(slideTimer);
      slideTimer = setInterval(() => moveHero(1), 7000);
    }

    function renderCategories() {
      const tiles = [
        ["odzywki-i-suplementy", "Suplementy", "Białko, aminokwasy i regeneracja"],
        ["odzywki-i-suplementy:witaminy-i-mineraly", "Witaminy", "Witaminy i minerały do codziennego wsparcia"],
        ["odzywki-i-suplementy:kreatyna", "Kreatyna", "Monohydraty i stacki kreatynowe"],
        ["sporty-walki", "Sporty walki", "Sprzęt do boksu, MMA i kickboxingu"],
        ["rekawice", "Rękawice", "Rękawice treningowe i sparingowe"],
        ["ochraniacze", "Ochraniacze", "Ochraniacze piszczeli, szczęki i głowy"],
        ["obuwie-sportowe", "Obuwie", "Buty treningowe i sportowe"],
        ["odziez", "Odzież", "Koszulki, bluzy, spodenki i rashguardy"],
        ["akcesoria", "Akcesoria", "Torby, shakery i akcesoria treningowe"],
        ["wyprzedaz", "Wyprzedaż", "Produkty w niższych cenach"]
      ];
      const categoryBySlug = Object.fromEntries(categories.map(category => [category.slug, category]));
      function tileImage(slug) {
        const specialMatch = products.find(product => matchesCategorySlug(product, slug));
        if (specialMatch) return productImage(specialMatch);
        const [categorySlug, subcategorySlug] = slug.split(":");
        const matched = products.find(product => product.categorySlug === categorySlug && (!subcategorySlug || product.subcategorySlug === subcategorySlug));
        return matched ? productImage(matched) : srcOf(categoryBySlug[categorySlug]?.image || "/products/shaker.png");
      }
      byId("categoryTiles").innerHTML = tiles.map(([slug, name, description]) => `
        <a class="category-card" href="${categoryHref(slug)}" data-category="${slug}">
          <span class="category-image"><img src="${tileImage(slug)}" alt="${escapeHtml(name)}" onerror="this.src=fallbackImage" /></span>
          <span class="category-body"><strong>${escapeHtml(name)}</strong><span>${escapeHtml(description)}</span></span>
        </a>
      `).join("");
    }

    function renderHomeBrands() {
      const brands = [...new Set(products.map(product => product.brand).filter(Boolean))]
        .sort((a, b) => a.localeCompare(b, "pl"))
        .slice(0, 12);
      const box = byId("homeBrandsGrid");
      if (!box) return;
      box.innerHTML = brands.map(brand =>
        '<a class="brand-tile" href="' + brandHref(brand) + '" data-brand-filter="' + escapeHtml(brand) + '">' + escapeHtml(brand) + '</a>'
      ).join("");
    }

    function productBadge(product, discount = discountPercent(product)) {
      if (discount) return '<span class="badge sale">Promocja -' + discount + '%</span>';
      if (product.status?.bestseller) return '<span class="badge">Bestseller</span>';
      if (product.status?.new) return '<span class="badge">Nowość</span>';
      return "";
    }

    function cartMiniIcon() {
      return '<span class="cart-mini-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M6 7h15l-2 9H8L6 7Z"/><path d="M6 7 5 3H2"/><circle cx="9" cy="20" r="1.7"/><circle cx="18" cy="20" r="1.7"/></svg></span>';
    }

    function card(product) {
      const discount = discountPercent(product);
      const href = productHref(product);
      return `
        <article class="product-card">
          <div class="product-photo">
            <a href="${href}" data-product="${product.id}" aria-label="Otwórz produkt ${escapeHtml(product.name)}">
              <img src="${productImage(product)}" alt="${escapeHtml(product.name)}" onerror="this.src=fallbackImage" />
            </a>
            <div class="badges">
              ${productBadge(product, discount)}
            </div>
          </div>
          <div class="product-body">
            <div class="brand-line">${escapeHtml(product.brand)}</div>
            <a class="product-name" href="${href}" data-product="${product.id}">${escapeHtml(product.name)}</a>
            <div class="product-meta">${escapeHtml(product.category)} / ${escapeHtml(product.subcategory || "Produkt")}</div>
            <div class="product-card-footer">
              <div class="price-line"><strong>${pln(product.price)}</strong>${product.oldPrice ? '<span class="old-price">' + pln(product.oldPrice) + '</span>' : ""}</div>
              <button class="product-quick-cart" type="button" data-add="${product.id}" aria-label="Dodaj ${escapeHtml(product.name)} do koszyka" title="Dodaj do koszyka">
                ${cartMiniIcon()}
              </button>
            </div>
          </div>
        </article>
      `;
    }

    function sectionProducts(filter, limit = 8) {
      return products.filter(filter).sort((a, b) => productScore(b) - productScore(a)).slice(0, limit);
    }

    function storedList(key) {
      try {
        return JSON.parse(localStorage.getItem(key) || "[]");
      } catch {
        return [];
      }
    }

    function writeStoredList(key, list) {
      try {
        localStorage.setItem(key, JSON.stringify(list));
      } catch {}
    }

    function rememberProduct(product) {
      if (!product) return;
      const viewed = [product.id, ...storedList("fightsports-viewed").filter(id => id !== product.id)].slice(0, 12);
      const viewedCategories = [product.categorySlug + ":" + product.subcategorySlug, product.categorySlug, ...storedList("fightsports-viewed-categories")]
        .filter(Boolean)
        .filter((value, index, arr) => arr.indexOf(value) === index)
        .slice(0, 10);
      writeStoredList("fightsports-viewed", viewed);
      writeStoredList("fightsports-viewed-categories", viewedCategories);
      renderProductSections();
    }

    function recommendedProducts(limit = 5) {
      const viewedIds = storedList("fightsports-viewed");
      const viewedCategories = storedList("fightsports-viewed-categories");
      if (viewedCategories.length) {
        const viewedSet = new Set(viewedIds);
        const related = products
          .filter(product => !viewedSet.has(product.id) && viewedCategories.some(slug => matchesCategorySlug(product, slug)))
          .sort((a, b) => productScore(b) - productScore(a));
        if (related.length) return related.slice(0, limit);
      }
      return sectionProducts(product => product.status?.recommended || product.status?.bestseller, limit);
    }

    function renderProductSections() {
      const newProducts = products.filter(p => p.status?.new).slice(0, 5);
      const bestProducts = sectionProducts(p => p.status?.bestseller, 5);
      const supplements = sectionProducts(p => p.categorySlug === "odzywki-i-suplementy", 5);
      const fight = sectionProducts(p => p.categorySlug === "sporty-walki", 5);
      const sale = sectionProducts(p => p.oldPrice || p.status?.sale || p.categorySlug === "wyprzedaz", 5);
      const recommended = recommendedProducts(5);
      byId("newProducts").innerHTML = newProducts.map(card).join("");
      byId("bestProducts").innerHTML = bestProducts.map(card).join("");
      byId("suppProducts").innerHTML = supplements.map(card).join("");
      byId("fightProducts").innerHTML = fight.map(card).join("");
      byId("saleProducts").innerHTML = sale.map(card).join("");
      byId("recommendedProducts").innerHTML = recommended.map(card).join("");
    }

    function matchesCategory(product) {
      return matchesCategorySlug(product, activeCategory);
    }

    function sortProducts(list, sort = "recommended") {
      const sorted = list.slice();
      if (sort === "price-asc") return sorted.sort((a, b) => a.price - b.price);
      if (sort === "price-desc") return sorted.sort((a, b) => b.price - a.price);
      if (sort === "sale") return sorted.sort((a, b) => Number(Boolean(b.oldPrice || b.status?.sale)) - Number(Boolean(a.oldPrice || a.status?.sale)) || productScore(b) - productScore(a));
      return sorted.sort((a, b) => productScore(b) - productScore(a));
    }

    function filteredProducts() {
      const query = normalize(catalogQuery);
      let list = products.filter(product => matchesCategory(product) && (!query || normalize(product.name + " " + product.brand + " " + product.category + " " + product.subcategory).includes(query)));
      return sortProducts(list, catalogSort);
    }

    function renderCatalog() {
      renderHeaderNav();
      const list = filteredProducts();
      const visible = list.slice(0, visibleCatalog);
      byId("catalogProducts").innerHTML = visible.length ? visible.map(card).join("") : '<div class="empty-state">Nie znaleziono produktów. Zmień kategorię albo wpisz inną frazę.</div>';
      byId("loadMoreButton").classList.toggle("hidden", visible.length >= list.length);
      const categorySelect = byId("catalogCategorySelect");
      const selectValue = Array.from(categorySelect.options).some(option => option.value === activeCategory) ? activeCategory : activeCategory.split(":")[0];
      categorySelect.value = selectValue;
    }

    function renderCatalogControls() {
      byId("catalogCategorySelect").innerHTML = '<option value="all">Wszystkie kategorie</option>' +
        categories.map(category => '<option value="' + category.slug + '">' + escapeHtml(category.name) + '</option>').join("") +
        '<option value="nowosci">Nowości</option><option value="wyprzedaz">Promocje</option>';
    }

    function setView(view) {
      byId("start").hidden = view !== "home";
      byId("categoryView").hidden = !["category", "search", "brand"].includes(view);
      byId("productView").hidden = view !== "product";

      if (view !== "home") {
        requestAnimationFrame(() => window.scrollTo(0, 0));
      }
    }

    function renderListingPage({ title, description, productsList, breadcrumbs, countLabel, view = "category" }) {
      currentListingProducts = productsList.slice();
      const sortSelect = byId("categorySortSelect");
      if (sortSelect) sortSelect.value = listingSort;
      byId("categoryBreadcrumbs").innerHTML = breadcrumbs;
      byId("categoryTitle").textContent = title;
      byId("categoryDescription").textContent = description;
      byId("categoryCount").textContent = countLabel || (productsList.length ? "Produkty: " + productsList.length : "Brak produktów");
      renderListingProducts();
      setView(view);
      document.title = title + " - FIGHTSPORTS";
      renderHeaderNav();
    }

    function renderListingProducts() {
      const list = sortProducts(currentListingProducts, listingSort);
      byId("categoryProducts").innerHTML = list.length ? list.map(card).join("") : '<div class="category-empty">Brak produktów w tej kategorii w aktualnym katalogu.</div>';
    }

    function renderCategoryPage(slug) {
      activeCategory = slug;
      catalogQuery = "";
      visibleCatalog = 32;
      const info = categoryInfo(slug);
      const list = categoryProductsForSlug(slug).sort((a, b) => productScore(b) - productScore(a));
      renderListingPage({
        title: info.name,
        description: info.description,
        productsList: list,
        breadcrumbs: renderBreadcrumbs(info, slug),
        view: "category"
      });
    }

    function renderSearchPage(query, push = true) {
      const cleanQuery = String(query || "").trim();
      catalogQuery = cleanQuery;
      activeCategory = "all";
      byId("headerSearchInput").value = cleanQuery;
      byId("mobileSearchInput").value = cleanQuery;
      const normalized = normalize(cleanQuery);
      const list = products
        .filter(product => !normalized || normalize(product.name + " " + product.brand + " " + product.category + " " + product.subcategory).includes(normalized))
        .sort((a, b) => productScore(b) - productScore(a));
      renderListingPage({
        title: cleanQuery ? 'Wyniki wyszukiwania: "' + cleanQuery + '"' : "Wyszukiwarka",
        description: cleanQuery ? "Produkty pasujące do wpisanej frazy." : "Wpisz frazę w wyszukiwarce, żeby znaleźć produkty FIGHTSPORTS.",
        productsList: list,
        breadcrumbs: '<button type="button" data-home-link>Strona główna</button><span>/</span><span>Wyszukiwarka</span>',
        countLabel: cleanQuery ? "Znaleziono: " + list.length : "Wpisz szukaną frazę",
        view: "search"
      });
      closeMobile();
      closeMega();
      if (push) safePush({ search: cleanQuery }, searchPath(cleanQuery));
    }

    function renderBrandPage(brand, push = true) {
      const cleanBrand = String(brand || "").trim();
      activeCategory = "all";
      catalogQuery = cleanBrand;
      const list = products
        .filter(product => normalize(product.brand) === normalize(cleanBrand))
        .sort((a, b) => productScore(b) - productScore(a));
      renderListingPage({
        title: cleanBrand,
        description: "Produkty producenta " + cleanBrand + " dostępne w sklepie FIGHTSPORTS.",
        productsList: list,
        breadcrumbs: '<button type="button" data-home-link>Strona główna</button><span>/</span><span>Producenci</span><span>/</span><span>' + escapeHtml(cleanBrand) + '</span>',
        view: "brand"
      });
      closeMobile();
      closeMega();
      if (push) safePush({ brand: cleanBrand }, brandPath(cleanBrand));
    }

    function showHome(push = true) {
      setView("home");
      activeCategory = "all";
      catalogQuery = "";
      visibleCatalog = 32;
      renderCatalog();
      closeMobile();
      closeMega();
      document.title = "FIGHTSPORTS - sklep sportowy";
      if (push) safePush({ home: true }, homePath());
    }

    function setCategory(slug, push = true) {
      renderCategoryPage(slug);
      closeMobile();
      closeMega();
      if (push) safePush({ category: slug }, categoryPath(slug));
    }

    function productBySlugOrId(value) {
      return products.find(item => item.id === value || productSlug(item) === value);
    }

    function productGallery(product) {
      const seen = new Set();
      const gallery = [product.image, ...(product.gallery || [])]
        .filter(Boolean)
        .map(srcOf)
        .filter(src => {
          if (!src || seen.has(src)) return false;
          seen.add(src);
          return true;
        });
      return gallery.length ? gallery.slice(0, 6) : [fallbackImage];
    }

    function optionItems(items, fallback) {
      const list = (items || []).map(item => {
        if (typeof item === "string") return { id: item, label: item };
        return { id: item.id || item.label || fallback, label: item.label || item.id || fallback };
      }).filter(item => item.label);
      return list.length ? list : [{ id: fallback, label: fallback }];
    }

    function productSizeItems(product) {
      const explicit = optionItems(product.sizes, "uniwersalny");
      const labels = explicit.map(item => String(item.label || "").trim());
      const generic = labels.length === 1 && /^(uniwersalny|standard)$/i.test(labels[0]);

      const fromVariants = (product.variants || []).map((item, index) => {
        const raw = String(typeof item === "string" ? item : (item.label || item.id || "")).trim();
        if (!raw) return null;
        const prefixed = raw.match(/^rozmiar\s*:\s*(.+)$/i);
        const clean = prefixed ? prefixed[1].trim() : raw;
        const sizeLike = Boolean(prefixed) ||
          /^(XXXS|XXS|XS|S|M|L|XL|XXL|XXXL)$/i.test(clean) ||
          /^\d+(?:[.,]\d+)?\s*oz$/i.test(clean) ||
          /^\d{2}(?:[.,]\d+)?$/.test(clean);
        if (!sizeLike) return null;
        return { id: (typeof item === "object" && item.id) ? item.id : "rozmiar-" + index, label: clean };
      }).filter(Boolean);

      if (fromVariants.length && (generic || fromVariants.length > explicit.length)) {
        const seen = new Set();
        return fromVariants.filter(item => {
          const key = item.label.toLowerCase();
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        });
      }

      return explicit.map(item => ({
        id: item.id,
        label: String(item.label || "").replace(/^rozmiar\s*:\s*/i, "").trim()
      }));
    }

    function selectOptions(items) {
      return items.map(item => '<option value="' + escapeHtml(item.id) + '">' + escapeHtml(item.label) + '</option>').join("");
    }

    function productDetailQty() {
      const input = byId("productQty");
      const value = Math.max(1, Math.min(99, parseInt(input?.value || "1", 10) || 1));
      if (input) input.value = value;
      return value;
    }

    function setProductDetailQty(delta) {
      const input = byId("productQty");
      if (!input) return;
      input.value = Math.max(1, Math.min(99, productDetailQty() + delta));
    }

    function renderProductPage(value, push = true) {
      const product = productBySlugOrId(value);
      if (!product) {
        renderSearchPage(value, false);
        return;
      }
      const discount = discountPercent(product);
      const categorySlug = product.categorySlug + (product.subcategorySlug ? ":" + product.subcategorySlug : "");
      const gallery = productGallery(product);
      const sizes = productSizeItems(product);
      const related = products
        .filter(item => item.id !== product.id && (item.subcategorySlug === product.subcategorySlug || item.categorySlug === product.categorySlug))
        .sort((a, b) => productScore(b) - productScore(a))
        .slice(0, 5);
      byId("productPageContent").innerHTML = `
        <nav class="breadcrumbs" aria-label="Ścieżka produktu">
          <button type="button" data-home-link>Strona główna</button><span>/</span>
          <a href="${categoryHref(product.categorySlug)}" data-category="${product.categorySlug}">${escapeHtml(product.category)}</a><span>/</span>
          <a href="${categoryHref(categorySlug)}" data-category="${categorySlug}">${escapeHtml(product.subcategory || "Produkt")}</a><span>/</span>
          <span>${escapeHtml(product.name)}</span>
        </nav>
        <section class="product-page-grid">
          <div class="product-page-gallery">
            <div class="product-page-photo">
              <img id="productMainImage" src="${escapeHtml(gallery[0])}" alt="${escapeHtml(product.name)}" onerror="this.src=fallbackImage" />
            </div>
            <div class="product-page-thumbs" aria-label="Zdjęcia produktu">
              ${gallery.map((src, index) => `
                <button class="product-thumb ${index === 0 ? "active" : ""}" type="button" data-product-image="${escapeHtml(src)}" aria-label="Pokaż zdjęcie ${index + 1}">
                  <img src="${escapeHtml(src)}" alt="${escapeHtml(product.name)} - zdjęcie ${index + 1}" onerror="this.src=fallbackImage" />
                </button>
              `).join("")}
            </div>
          </div>
          <article class="product-page-summary">
            <div class="brand-line">${escapeHtml(product.brand)}</div>
            <h1>${escapeHtml(product.name)}</h1>
            <span class="availability">Dostępny, wysyłka 24h</span>
            <div class="badges" style="position:static">${productBadge(product, discount)}</div>
            <div class="price-line"><strong>${pln(product.price)}</strong>${product.oldPrice ? '<span class="old-price">' + pln(product.oldPrice) + '</span>' : ""}</div>
            <div class="product-choice-grid">
              <label class="field" for="productSizeSelect"><span>Rozmiar</span><select id="productSizeSelect">${selectOptions(sizes)}</select></label>
            </div>
            <label class="quantity-field" for="productQty">
              <span>Ilość</span>
              <span class="quantity-control">
                <button type="button" data-product-qty="-1" aria-label="Zmniejsz ilość">-</button>
                <input id="productQty" type="number" min="1" max="99" value="1" inputmode="numeric" />
                <button type="button" data-product-qty="1" aria-label="Zwiększ ilość">+</button>
              </span>
            </label>
            <div class="product-page-actions">
              <button class="cart-button" type="button" data-add-detail="${product.id}">${cartMiniIcon()}<span>Dodaj do koszyka</span></button>
              <button class="primary-button" type="button" data-buy-detail="${product.id}">Kup teraz</button>
            </div>
            <div class="product-page-meta">
              <span class="chip">${escapeHtml(product.category)}</span>
              <span class="chip">${escapeHtml(product.subcategory || "Produkt")}</span>
              <span class="chip">Ocena ${Number(product.rating || 0).toFixed(1)}/5</span>
              <span class="chip">${product.reviewsCount || 0} opinii</span>
              <span class="chip">Magazyn: ${product.stock || 0} szt.</span>
            </div>
          </article>
        </section>
        <section class="product-lower-grid" aria-label="Szczegóły produktu">
          <article class="product-info-panel">
            <h3>Opis produktu</h3>
            <p>${escapeHtml(product.description || product.shortDescription || "Produkt dostępny w sklepie FIGHTSPORTS.")}</p>
          </article>
          <article class="product-info-panel">
            <h3>Parametry</h3>
            <div class="info-grid" style="margin-top:0">
              <div class="info-box"><strong>Marka</strong><span>${escapeHtml(product.brand)}</span></div>
              <div class="info-box"><strong>Kategoria</strong><span>${escapeHtml(product.category)}</span></div>
              <div class="info-box"><strong>Rozmiar</strong><span>${sizes.map(item => escapeHtml(item.label)).join(", ")}</span></div>
            </div>
          </article>
          <article class="product-info-panel">
            <h3>Dostawa</h3>
            <p>Wysyłka 24h z Polski. Dostępne metody: Paczkomat, kurier, ORLEN Paczka, Pocztex oraz odbiór osobisty.</p>
          </article>
        </section>
        <section class="related-section">
          <div class="section-head">
            <div>
              <p class="section-kicker">Podobne</p>
              <h2 class="section-title">Produkty z tej kategorii</h2>
            </div>
          </div>
          <div class="products-grid">${related.map(card).join("")}</div>
        </section>
      `;
      setView("product");
      closeMobile();
      closeMega();
      rememberProduct(product);
      document.title = product.name + " - FIGHTSPORTS";
      if (push) safePush({ product: product.id }, productPath(product));
    }

    function openProduct(id) {
      const product = productBySlugOrId(id);
      if (product) window.location.href = productPath(product);
    }

    function readCart() {
      try {
        return JSON.parse(localStorage.getItem("fightsports-cart") || "[]");
      } catch {
        return [];
      }
    }

    function saveCart() {
      localStorage.setItem("fightsports-cart", JSON.stringify(cart));
    }

    function addToCart(id, qty = 1) {
      const product = products.find(item => item.id === id);
      if (!product) return;
      const amount = Math.max(1, Math.min(99, Number(qty) || 1));
      const line = cart.find(item => item.id === id);
      if (line) line.qty += amount;
      else cart.push({ id, qty: amount });
      saveCart();
      renderCart();
      showToast((amount > 1 ? amount + " x " : "") + "Dodano do koszyka: " + product.name);
    }

    function changeQty(id, delta) {
      cart = cart.map(item => item.id === id ? { ...item, qty: item.qty + delta } : item).filter(item => item.qty > 0);
      saveCart();
      renderCart();
    }

    function removeFromCart(id) {
      cart = cart.filter(item => item.id !== id);
      saveCart();
      renderCart();
    }

    function cartLines() {
      return cart.map(item => ({ ...item, product: products.find(product => product.id === item.id) })).filter(item => item.product);
    }

    function cartTotal() {
      return cartLines().reduce((sum, item) => sum + item.product.price * item.qty, 0);
    }

    function cartPath() {
      return pageRootPrefix() + "cart.html";
    }

    function checkoutPath() {
      return pageRootPrefix() + "checkout.html";
    }

    function openCart(push = true) {
      closeMobile();
      closeMega();
      const isCartPage = location.pathname.match(/\/(?:koszyk\/?|cart\.html)$/);
      if (isCartPage) return;
      window.location.href = cartPath();
    }

    function closeCart() {
      const drawer = byId("cartDrawer");
      if (!drawer) return;
      drawer.classList.remove("open");
      drawer.setAttribute("aria-hidden", "true");
    }

    function renderCart() {
      const lines = cartLines();
      const count = lines.reduce((sum, item) => sum + item.qty, 0);
      const hasItems = count > 0;
      document.body.classList.toggle("cart-has-items", hasItems);

      // The desktop quick-cart button is now also visible on mobile.
      // Create its count badge at runtime so every generated page gets it
      // without duplicating markup across hundreds of static pages.
      document.querySelectorAll(".floating-button").forEach(button => {
        if (!button.querySelector(".floating-cart-badge")) {
          const badge = document.createElement("span");
          badge.className = "floating-cart-badge";
          badge.setAttribute("data-cart-count", "");
          badge.hidden = true;
          badge.textContent = "0";
          button.appendChild(badge);
        }
      });

      document.querySelectorAll("[data-cart-count]").forEach(node => {
        node.textContent = count;
        node.hidden = !hasItems;
      });
      document.querySelectorAll(".header-cart-button").forEach(button => {
        button.classList.toggle("is-active", hasItems);
        button.setAttribute("aria-label", hasItems ? "Koszyk, produktów: " + count : "Koszyk jest pusty");
      });
      byId("cartTotal").textContent = pln(cartTotal());
      byId("quickCartTotal").textContent = pln(cartTotal());
      byId("cartItems").innerHTML = lines.length ? lines.map(line => cartLine(line)).join("") : '<div class="empty-state">Koszyk jest pusty. Dodaj produkt z karty albo z widoku szczegółów.</div>';
      byId("quickCartItems").innerHTML = lines.length ? lines.slice(0, 4).map(line => `
        <div class="quick-line">
          <img src="${productImage(line.product)}" alt="${escapeHtml(line.product.name)}" onerror="this.src=fallbackImage" />
          <div><strong>${escapeHtml(line.product.name)}</strong><span>${line.qty} x ${pln(line.product.price)}</span></div>
          <button class="outline-button" type="button" data-remove="${line.id}">Usuń</button>
        </div>
      `).join("") + '<button class="primary-button" type="button" data-open-cart>Przejdź do koszyka</button>' : '<div class="empty-state">Koszyk jest pusty.</div>';

      const dedicatedItems = byId("dedicatedCartItems");
      if (dedicatedItems) {
        dedicatedItems.innerHTML = lines.length ? lines.map(line => cartPageLine(line)).join("") : `
          <div class="cart-empty-box">
            <h2>W koszyku nie ma jeszcze produktów</h2>
            <p>Dodaj coś ze sklepu, a produkty pojawią się tutaj.</p>
            <a class="primary-button" href="${homePath()}">Kontynuuj zakupy</a>
          </div>
        `;
        const dedicatedCount = byId("dedicatedCartCount");
        const dedicatedSubtotal = byId("dedicatedCartSubtotal");
        const dedicatedTotal = byId("dedicatedCartTotal");
        const dedicatedCheckoutButton = byId("dedicatedCheckoutButton");
        if (dedicatedCount) dedicatedCount.textContent = "Produkty (" + count + " szt.)";
        if (dedicatedSubtotal) dedicatedSubtotal.textContent = pln(cartTotal());
        if (dedicatedTotal) dedicatedTotal.textContent = pln(cartTotal());
        if (dedicatedCheckoutButton) dedicatedCheckoutButton.disabled = !hasItems;
      }

      renderCheckoutPage();
    }

    function cartLine(line) {
      const product = line.product;
      return `
        <div class="cart-line">
          <img src="${productImage(product)}" alt="${escapeHtml(product.name)}" onerror="this.src=fallbackImage" />
          <div>
            <strong>${escapeHtml(product.name)}</strong>
            <span>${pln(product.price)} / szt.</span>
            <div class="qty-row">
              <button type="button" data-qty="${product.id}" data-delta="-1">-</button>
              <b>${line.qty}</b>
              <button type="button" data-qty="${product.id}" data-delta="1">+</button>
              <button class="remove" type="button" data-remove="${product.id}">Usuń</button>
            </div>
          </div>
        </div>
      `;
    }


    function cartPageLine(line) {
      const product = line.product;
      return `
        <article class="cart-page-line">
          <img src="${productImage(product)}" alt="${escapeHtml(product.name)}" onerror="this.src=fallbackImage" />
          <div class="cart-page-info">
            <div class="cart-page-brand">${escapeHtml(product.brand || "FIGHTSPORTS")}</div>
            <a class="cart-page-name" href="${productPath(product)}">${escapeHtml(product.name)}</a>
            <span class="cart-page-unit">${pln(product.price)} / szt.</span>
            <div class="cart-page-qty">
              <button type="button" data-qty="${product.id}" data-delta="-1" aria-label="Zmniejsz ilość">−</button>
              <b>${line.qty}</b>
              <button type="button" data-qty="${product.id}" data-delta="1" aria-label="Zwiększ ilość">+</button>
              <button class="cart-page-remove" type="button" data-remove="${product.id}">Usuń</button>
            </div>
          </div>
          <div class="cart-page-line-total">${pln(product.price * line.qty)}</div>
        </article>
      `;
    }

    function openCheckout() {
      const lines = cartLines();
      if (!lines.length) {
        showToast("Koszyk jest pusty.");
        return;
      }
      window.location.href = checkoutPath();
    }

    function renderCheckoutPage() {
      const itemsNode = byId("checkoutPageItems");
      if (!itemsNode) return;
      const lines = cartLines();
      itemsNode.innerHTML = lines.length ? lines.map(line => `
        <div class="checkout-mini-line">
          <img src="${productImage(line.product)}" alt="${escapeHtml(line.product.name)}" onerror="this.src=fallbackImage" />
          <div>
            <strong>${escapeHtml(line.product.name)}</strong>
            <small>${line.qty} x ${pln(line.product.price)}</small>
          </div>
          <b>${pln(line.product.price * line.qty)}</b>
        </div>
      `).join("") : '<div class="empty-state">Koszyk jest pusty.</div>';

      const subtotalNode = byId("checkoutPageSubtotal");
      const totalNode = byId("checkoutPageTotal");
      const orderButton = byId("placeOrderButton");
      if (subtotalNode) subtotalNode.textContent = pln(cartTotal());
      if (totalNode) totalNode.textContent = pln(cartTotal());
      if (orderButton) orderButton.disabled = !lines.length;
    }

    function renderFooter() {
      const company = `
        <div class="footer-col">
          <h3>FIGHTSPORTS</h3>
          <p>Polski sklep z produktami do sportów walki, suplementami, odzieżą i akcesoriami treningowymi.</p>
          <p>C.H. Korej, ul. Wernera 10, 26-600 Radom<br>info@fightsports.pl<br>48 385 84 34 / 608 690 783</p>
          <div class="payment-tags">${["BLIK","PayU","Przelewy24","VISA","Mastercard","PayPo","Pobranie"].map(item => '<span>' + item + '</span>').join("")}</div>
        </div>
      `;
      const columns = footerSections.map(([title, links]) => `
        <div class="footer-col">
          <h3>${escapeHtml(title)}</h3>
          <div class="footer-links">${links.map(([label, target]) => footerLink(label, target)).join("")}</div>
        </div>
      `).join("");
      byId("footerDesktop").innerHTML = company + columns;
      byId("footerMobile").innerHTML = footerSections.map(([title, links]) => `
        <div class="footer-accordion">
          <button class="footer-accordion-title" type="button" data-footer-accordion>${escapeHtml(title)} <span>+</span></button>
          <div class="footer-accordion-body">${links.map(([label, target]) => footerLink(label, target)).join("")}</div>
        </div>
      `).join("");
    }

    function footerLink(label, target) {
      if (String(target).startsWith("http")) return '<a href="' + target + '" rel="noreferrer">' + escapeHtml(label) + '</a>';
      if (target === "cart") return '<a href="' + cartPath() + '">' + escapeHtml(label) + '</a>';
      if (target === "checkout") return '<a href="' + checkoutPath() + '">' + escapeHtml(label) + '</a>';
      if (target === "account") return '<button type="button" data-open-account>' + escapeHtml(label) + '</button>';
      if (["regulamin", "polityka", "dane", "zwroty", "kontakt", "onas"].includes(target)) return '<button type="button" data-info="' + target + '">' + escapeHtml(label) + '</button>';
      return '<a href="' + categoryHref(target) + '" data-category="' + target + '">' + escapeHtml(label) + '</a>';
    }

    function openInfo(kind) {
      const copy = {
        regulamin: ["Regulamin", "Widok demonstracyjny: tu znajduje się miejsce na regulamin sklepu, zasady zamówień i obsługi klienta."],
        polityka: ["Polityka prywatności", "Widok demonstracyjny: tu znajduje się miejsce na informacje RODO, pliki cookies i przetwarzanie danych."],
        onas: ["O FIGHTSPORTS", "FIGHTSPORTS.PL to polski sklep sportowy specjalizujący się w suplementach, odżywkach, sprzęcie do sportów walki, odzieży sportowej i akcesoriach treningowych. Marka działa od 2000 roku i stawia na sprawdzone produkty oraz fachowe doradztwo."],
        dane: ["Dane firmy", "Sprint Jarosław Krawczyk, 26-600 Radom, ul. Wernera 10. NIP: 948-197-76-57, REGON: 670133021."],
        producenci: ["Producenci", "W sklepie znajdziesz marki znane ze sportów walki, suplementacji i treningu: Olimp, Trec, Activlab, Pit Bull, Extreme Hobby, Gorilla Wear, Masters, Leone, Under Armour i inne."],
        zwroty: ["Zwroty i reklamacje", "Zwrot standardowo w ciągu 14 dni od odbioru. Produkt powinien być kompletny i bez śladów użycia."],
        kontakt: ["Kontakt", "C.H. Korej, ul. Wernera 10, Radom: 48 385 84 34 / 608 690 783, info@fightsports.pl. C.H. Feniks, ul. Staroopatowska 20 przy Śląskiej: 694 624 632."]
      }[kind] || ["Informacja", "Sekcja informacyjna sklepu."];
      byId("checkoutBox").innerHTML = '<div class="detail-top"><h2>' + copy[0] + '</h2><button class="close-button" type="button" data-close-checkout>X</button></div><p>' + copy[1] + '</p>';
      byId("checkoutModal").classList.add("open");
    }

    function openMobile() {
      closeMega();
      if (window.FSMobileNav && typeof window.FSMobileNav.open === "function") {
        window.FSMobileNav.open();
        return;
      }
      const drawer = byId("mobileDrawer");
      if (!drawer) return;
      drawer.classList.add("open");
      drawer.setAttribute("aria-hidden", "false");
      document.body.classList.add("mobile-menu-open");
    }

    function closeMobile() {
      if (window.FSMobileNav && typeof window.FSMobileNav.close === "function") {
        window.FSMobileNav.close();
        return;
      }
      const drawer = byId("mobileDrawer");
      if (!drawer) return;
      drawer.classList.remove("open");
      drawer.setAttribute("aria-hidden", "true");
      document.body.classList.remove("mobile-menu-open");
    }

    function openMega(type) {
      if (window.innerWidth <= 860) {
        if (type === "categories") openMobile();
        if (type === "brands") openInfo("producenci");
        if (type === "about") openInfo("onas");
        return;
      }
      const layer = byId("megaLayer");
      if (!layer) return;
      activeMega = type;
      layer.classList.add("open");
      layer.setAttribute("aria-hidden", "false");
      document.querySelectorAll("[data-mega-panel]").forEach(panel => {
        panel.classList.toggle("active", panel.dataset.megaPanel === type);
      });
      document.querySelectorAll("[data-mega]").forEach(button => {
        button.classList.toggle("active", button.dataset.mega === type);
      });
    }

    function closeMega() {
      const layer = byId("megaLayer");
      if (!layer) return;
      activeMega = "";
      layer.classList.remove("open");
      layer.setAttribute("aria-hidden", "true");
      document.querySelectorAll("[data-mega]").forEach(button => button.classList.remove("active"));
    }

    function setMegaTab(name) {
      document.querySelectorAll("[data-mega-tab]").forEach(button => {
        button.classList.toggle("active", button.dataset.megaTab === name);
      });
      document.querySelectorAll("[data-mega-content]").forEach(panel => {
        panel.classList.toggle("active", panel.dataset.megaContent === name);
      });
    }

    function filterBrand(brand) {
      window.location.href = brandPath(brand);
    }

    function showToast(message) {
      const toast = byId("toast");
      toast.textContent = message;
      toast.classList.add("show");
      clearTimeout(showToast.timer);
      showToast.timer = setTimeout(() => toast.classList.remove("show"), 2200);
    }

    function bindQuickCartHover() {
      const floatingCart = document.querySelector(".floating-cart");
      const quickCart = byId("quickCart");
      const floatingButton = floatingCart?.querySelector(".floating-button");
      if (!floatingCart || !quickCart || !floatingButton) return;

      const hoverCapable = window.matchMedia && window.matchMedia("(hover: hover) and (pointer: fine)").matches;
      let hideTimer = 0;
      const showQuickCart = () => {
        window.clearTimeout(hideTimer);
        floatingCart.classList.add("is-quick-cart-open");
        quickCart.classList.add("open");
        floatingButton.setAttribute("aria-expanded", "true");
      };
      const hideQuickCart = () => {
        window.clearTimeout(hideTimer);
        floatingCart.classList.remove("is-quick-cart-open");
        quickCart.classList.remove("open");
        floatingButton.setAttribute("aria-expanded", "false");
      };
      const scheduleQuickCartHide = () => {
        window.clearTimeout(hideTimer);
        hideTimer = window.setTimeout(hideQuickCart, 320);
      };

      floatingButton.setAttribute("aria-haspopup", "dialog");
      floatingButton.setAttribute("aria-expanded", "false");

      if (hoverCapable) {
        floatingCart.addEventListener("mouseenter", showQuickCart);
        floatingCart.addEventListener("mouseleave", scheduleQuickCartHide);
        quickCart.addEventListener("mouseenter", showQuickCart);
        quickCart.addEventListener("mouseleave", scheduleQuickCartHide);
      } else {
        // Touch/mobile: first tap opens a real quick-cart preview.
        // The button inside the preview still navigates to the full cart page.
        floatingButton.addEventListener("click", event => {
          event.preventDefault();
          event.stopPropagation();
          const isOpen = quickCart.classList.contains("open");
          if (isOpen) hideQuickCart(); else showQuickCart();
        });
        document.addEventListener("pointerdown", event => {
          if (!floatingCart.contains(event.target)) hideQuickCart();
        }, { passive: true });
      }
    }

    function bindEvents() {
      document.addEventListener("click", event => {
        const target = event.target.closest("button, a");
        if (!target) return;
        if (target.matches("[data-mega]")) {
          event.preventDefault();
          openMega(target.dataset.mega);
          return;
        }
        if (target.matches("[data-close-mega]")) {
          closeMega();
          return;
        }
        if (target.matches("[data-mega-tab]")) {
          setMegaTab(target.dataset.megaTab);
          return;
        }
        if (target.matches("[data-brand-filter]")) {
          closeMobile();
          closeMega();
          if (target.tagName === "A" && target.getAttribute("href")) return;
          event.preventDefault();
          filterBrand(target.dataset.brandFilter);
          return;
        }
        if (target.matches("[data-category]")) {
          closeMobile();
          closeMega();
          if (target.tagName === "A" && target.getAttribute("href")) return;
          event.preventDefault();
          window.location.href = categoryPath(target.dataset.category);
          return;
        }
        if (target.matches("[data-home-link]")) {
          closeMobile();
          closeMega();
          if (target.tagName === "A" && target.getAttribute("href")) return;
          event.preventDefault();
          window.location.href = homePath();
          return;
        }
        if (target.matches("[data-hero-prev]")) moveHero(-1);
        if (target.matches("[data-hero-next]")) moveHero(1);
        if (target.matches("[data-hero-dot]")) {
          const nextIndex = Number(target.dataset.heroDot);
          if (nextIndex !== activeSlide) {
            const directDistance = nextIndex - activeSlide;
            const wrappedDistance = directDistance > 0 ? directDistance - heroSlides.length : directDistance + heroSlides.length;
            const direction = Math.abs(directDistance) <= Math.abs(wrappedDistance) ? Math.sign(directDistance) : Math.sign(wrappedDistance);
            animateHeroTo(nextIndex, direction || 1);
          }
          restartHeroTimer();
        }
        if (target.matches("[data-product]")) {
          if (target.tagName === "A" && target.getAttribute("href")) return;
          event.preventDefault();
          openProduct(target.dataset.product);
          return;
        }
        if (target.matches("[data-product-image]")) {
          const mainImage = byId("productMainImage");
          if (mainImage) mainImage.src = target.dataset.productImage;
          document.querySelectorAll("[data-product-image]").forEach(button => button.classList.toggle("active", button === target));
          return;
        }
        if (target.matches("[data-product-qty]")) {
          setProductDetailQty(Number(target.dataset.productQty));
          return;
        }
        if (target.matches("[data-add-detail]")) {
          addToCart(target.dataset.addDetail, productDetailQty());
          return;
        }
        if (target.matches("[data-buy-detail]")) {
          addToCart(target.dataset.buyDetail, productDetailQty());
          openCart();
          return;
        }
        if (target.matches("[data-add]")) addToCart(target.dataset.add);
        if (target.matches("[data-buy]")) {
          addToCart(target.dataset.buy);
          openCart();
        }
        if (target.matches("[data-open-cart]")) openCart();
        if (target.matches("[data-close-cart]")) closeCart();
        if (target.matches("[data-qty]")) changeQty(target.dataset.qty, Number(target.dataset.delta));
        if (target.matches("[data-remove]")) removeFromCart(target.dataset.remove);
        if (target.matches("[data-open-checkout]")) openCheckout();
        if (target.matches("[data-close-checkout]")) byId("checkoutModal").classList.remove("open");
        if (target.matches("[data-open-account]")) byId("accountModal").classList.add("open");
        if (target.matches("[data-close-account]")) byId("accountModal").classList.remove("open");
        if (target.matches("[data-footer-accordion]")) target.closest(".footer-accordion").classList.toggle("open");
        if (target.matches("[data-info]")) {
          event.preventDefault();
          openInfo(target.dataset.info);
          closeMega();
          closeMobile();
        }
      });

      byId("checkoutModal").addEventListener("click", event => {
        if (event.target.id === "checkoutModal") byId("checkoutModal").classList.remove("open");
      });
      byId("accountModal").addEventListener("click", event => {
        if (event.target.id === "accountModal") byId("accountModal").classList.remove("open");
      });
      const megaLayer = byId("megaLayer");
      if (megaLayer) {
        megaLayer.addEventListener("click", event => {
          if (event.target.id === "megaLayer") closeMega();
        });
        megaLayer.addEventListener("mouseleave", closeMega);
      }
      document.querySelectorAll("[data-mega]").forEach(button => {
        button.addEventListener("mouseenter", () => openMega(button.dataset.mega));
        button.addEventListener("focus", () => openMega(button.dataset.mega));
      });

      byId("headerSearch").addEventListener("submit", event => {
        event.preventDefault();
        window.location.href = searchPath(byId("headerSearchInput").value);
      });
      const mobileSearch = byId("mobileSearch");
      if (mobileSearch) {
        mobileSearch.addEventListener("submit", event => {
          event.preventDefault();
          const input = byId("mobileSearchInput");
          window.location.href = searchPath(input ? input.value : "");
        });
      }
      byId("catalogSearchInput").addEventListener("input", event => {
        catalogQuery = event.target.value;
        visibleCatalog = 32;
        renderCatalog();
      });
      byId("catalogCategorySelect").addEventListener("change", event => {
        window.location.href = categoryPath(event.target.value);
      });
      byId("catalogSortSelect").addEventListener("change", event => {
        catalogSort = event.target.value;
        renderCatalog();
      });
      byId("categorySortSelect").addEventListener("change", event => {
        listingSort = event.target.value;
        renderListingProducts();
      });
      byId("loadMoreButton").addEventListener("click", () => {
        visibleCatalog += 32;
        renderCatalog();
      });
      byId("accountForm").addEventListener("submit", event => {
        event.preventDefault();
        byId("accountModal").classList.remove("open");
        showToast("Zapisano dane kontaktowe konta.");
      });

      const checkoutForm = byId("checkoutForm");
      if (checkoutForm) {
        checkoutForm.addEventListener("submit", event => {
          event.preventDefault();
          if (!cartLines().length) {
            showToast("Koszyk jest pusty.");
            window.location.href = cartPath();
            return;
          }
          const button = byId("placeOrderButton");
          if (button) button.textContent = "Zamówienie gotowe do podsumowania";
          showToast("Dane zapisane lokalnie. Kolejny krok to integracja płatności WooCommerce.");
        });
      }
      byId("bottomNewsletterForm").addEventListener("submit", event => {
        event.preventDefault();
        event.currentTarget.reset();
        showToast("Dziękujemy za zapis do newslettera FIGHTSPORTS.");
      });
      document.addEventListener("keydown", event => {
        if (event.key === "Escape") {
          closeMobile();
          closeMega();
          closeCart();
          byId("checkoutModal").classList.remove("open");
          byId("accountModal").classList.remove("open");
        }
      });
      window.addEventListener("popstate", routeFromLocation);
    }

    function routeFromLocation() {
      const routedPath = new URLSearchParams(location.search).get("route");
      if (routedPath) {
        try {
          history.replaceState({ routed: true }, "", routedPath);
        } catch {}
      }
      const isCartRoute = location.pathname.match(/\/(?:koszyk\/?|cart\.html)$/);
      const isCheckoutRoute = location.pathname.match(/\/(?:zamowienie\/?|checkout\.html)$/);
      document.body.classList.toggle("is-cart-page", Boolean(isCartRoute));
      document.body.classList.toggle("is-checkout-page", Boolean(isCheckoutRoute));
      closeCart();
      const productRoute = productFromLocation();
      if (productRoute) {
        renderProductPage(productRoute, false);
        return;
      }
      const brandRoute = brandFromLocation();
      if (brandRoute) {
        renderBrandPage(brandRoute, false);
        return;
      }
      if (location.pathname.match(/\/(?:szukaj\/?|search\.html)$/)) {
        renderSearchPage(searchFromLocation(), false);
        return;
      }
      const categoryRoute = categoryFromLocation();
      if (categoryRoute) {
        setCategory(categoryRoute, false);
        return;
      }
      showHome(false);
      if (location.pathname.match(/\/(?:moje-konto\/?|account\.html)$/)) byId("accountModal").classList.add("open");
    }

    function init() {
      setAssetImages();
      renderHeaderNav();
      renderHero();
      renderCategories();
      renderHomeBrands();
      renderProductSections();
      renderCatalogControls();
      renderCatalog();
      renderCart();
      renderFooter();
      syncStaticLinks();
      bindEvents();
      bindQuickCartHover();
      bindHeroSwipe();
      routeFromLocation();
      restartHeroTimer();
    }

    init();